module com.example.model {
    requires com.fasterxml.jackson.databind;

    // Compile-time public access for other modules:
    exports com.example.model.dto;

    // Runtime reflection only for Jackson deserialization:
    opens com.example.model.dto to com.fasterxml.jackson.databind;
}

// Module: java.sql
module java.sql {
    // java.logging is required transitively because java.sql public APIs expose logging types:
    requires transitive java.logging;
    requires transitive java.xml;
    exports java.sql;
}

// In provider module:
module com.example.codec.mp3 {
    requires com.example.codec.api;
    provides com.example.codec.api.AudioCodec with com.example.codec.mp3.Mp3Codec;
}

// In consumer module:
module com.example.player {
    requires com.example.codec.api;
    uses com.example.codec.api.AudioCodec;
}

